from . import point as pt

POINTS = [
pt('A1', 'articles', ('Le genre et les articles',
 "Masculin en -o (pluriel -i), féminin en -a (pluriel -e) ; les noms en -e sont de l'un ou l'autre genre (pluriel -i) : il libro → i libri, la casa → le case, il fiore → i fiori.\nArticles définis : il / i ; lo / gli devant s + consonne, z, gn, ps (lo studente, gli studenti) ; l' devant voyelle (l'amico, gli amici) ; la / le (l'amica, le amiche).\nIndéfinis : un, uno, una, un'."),
 ('Gender and articles',
 "Masculine in -o (plural -i), feminine in -a (plural -e); nouns in -e can be either (plural -i): il libro → i libri, la casa → le case, il fiore → i fiori.\nDefinite articles: il / i; lo / gli before s + consonant, z, gn, ps (lo studente, gli studenti); l' before a vowel (l'amico, gli amici); la / le (l'amica, le amiche).\nIndefinite: un, uno, una, un'."),
 [("Il libro è sul tavolo.", "Le livre est sur la table.", "The book is on the table."), ("Gli studenti sono in classe.", "Les étudiants sont en classe.", "The students are in class.")],
 r"\b(il|lo|la|i|gli|le)\b", ['il', 'lo', 'la', 'i', 'gli', 'le']),
pt('A1', 'essere-avere', ('Essere et avere',
 "essere : sono, sei, è, siamo, siete, sono. avere : ho, hai, ha, abbiamo, avete, hanno.\nLe pronom sujet est généralement omis. « C'è » + singulier, « ci sono » + pluriel = il y a.\nAvec avere : ho fame, ho sete, ho vent'anni, ho freddo, ho ragione."),
 ('Essere and avere',
 "essere: sono, sei, è, siamo, siete, sono. avere: ho, hai, ha, abbiamo, avete, hanno.\nSubject pronouns are usually dropped. “C'è” + singular, “ci sono” + plural = there is / are.\nWith avere: ho fame (I'm hungry), ho sete, ho vent'anni, ho freddo, ho ragione."),
 [("Sono italiano.", "Je suis italien.", "I am Italian."), ("Ho due fratelli.", "J'ai deux frères.", "I have two brothers."), ("C'è un problema.", "Il y a un problème.", "There is a problem.")],
 r"\b(sono|sei|è|siamo|siete|ho|hai|ha|abbiamo|hanno)\b", ['sono', 'sei', 'è', 'siamo', 'ho', 'hai', 'ha', 'hanno']),
pt('A1', 'present', ('Le présent des verbes réguliers',
 "parlare : parlo, parli, parla, parliamo, parlate, parlano.\nprendere : prendo, prendi, prende, prendiamo, prendete, prendono.\ndormire : dormo, dormi, dorme, dormiamo, dormite, dormono. Certains verbes en -ire intercalent -isc- : finisco, finisci, finisce, finiamo, finite, finiscono (capire, preferire).\nNégation : « non » devant le verbe."),
 ('The present of regular verbs',
 "parlare: parlo, parli, parla, parliamo, parlate, parlano.\nprendere: prendo, prendi, prende, prendiamo, prendete, prendono.\ndormire: dormo, dormi, dorme, dormiamo, dormite, dormono. Some -ire verbs insert -isc-: finisco, finisci, finisce, finiamo, finite, finiscono (capire, preferire).\nNegative: “non” before the verb."),
 [("Parlo italiano.", "Je parle italien.", "I speak Italian."), ("Non capisco.", "Je ne comprends pas.", "I don't understand.")],
 r"\b(parlo|parli|parla|parliamo|capisco|capisci|capisce|vivo|vive|abito|lavoro|lavora)\b", None),
pt('A1', 'irreguliers', ('Présent : verbes irréguliers courants',
 "andare : vado, vai, va, andiamo, andate, vanno. fare : faccio, fai, fa, facciamo, fate, fanno. venire : vengo, vieni, viene. dire : dico, dici, dice. stare : sto, stai, sta. dare : do, dai, dà. sapere : so, sai, sa. uscire : esco, esci, esce.\nModaux : potere (posso, puoi, può), volere (voglio, vuoi, vuole), dovere (devo, devi, deve), suivis de l'infinitif."),
 ('Present: common irregular verbs',
 "andare: vado, vai, va, andiamo, andate, vanno. fare: faccio, fai, fa, facciamo, fate, fanno. venire: vengo, vieni, viene. dire: dico, dici, dice. stare: sto, stai, sta. dare: do, dai, dà. sapere: so, sai, sa. uscire: esco, esci, esce.\nModals: potere (posso, puoi, può), volere (voglio, vuoi, vuole), dovere (devo, devi, deve), followed by the infinitive."),
 [("Vado a casa.", "Je vais à la maison.", "I am going home."), ("Che cosa fai?", "Qu'est-ce que tu fais ?", "What are you doing?"), ("Posso entrare?", "Puis-je entrer ?", "May I come in?")],
 r"\b(vado|vai|va|andiamo|vanno|faccio|fai|fa|posso|puoi|può|voglio|vuoi|vuole|devo|devi|deve)\b", None),
pt('A1', 'adjectifs', ("L'adjectif et les possessifs",
 "L'adjectif s'accorde : rosso, rossa, rossi, rosse ; ceux en -e ont deux formes (grande, grandi). Il suit généralement le nom : una macchina rossa.\nLes possessifs prennent l'article : il mio libro, la tua casa, i suoi amici. Pas d'article avec un nom de parenté au singulier : mia madre, tuo fratello (mais i miei genitori)."),
 ('Adjectives and possessives',
 "Adjectives agree: rosso, rossa, rossi, rosse; those in -e have two forms (grande, grandi). They usually follow the noun: una macchina rossa.\nPossessives take the article: il mio libro, la tua casa, i suoi amici. No article with a singular family noun: mia madre, tuo fratello (but i miei genitori)."),
 [("La mia casa è piccola.", "Ma maison est petite.", "My house is small."), ("Mio padre è medico.", "Mon père est médecin.", "My father is a doctor.")],
 r"\b(mio|mia|miei|mie|tuo|tua|suo|sua|nostro|nostra)\b", ['mio', 'mia', 'tuo', 'tua', 'suo', 'sua']),
pt('A1', 'prepositions', ('Les prépositions et leurs contractions',
 "a (à), di (de), da (depuis, de chez, par), in (dans, en), su (sur), con, per, tra / fra.\nElles fusionnent avec l'article : a + il = al, di + il = del, da + il = dal, in + il = nel, su + il = sul ; de même allo, alla, ai, agli, alle ; della, nella, sulla…\nVilles : a Roma ; pays : in Italia. Chez quelqu'un : da Maria."),
 ('Prepositions and their contractions',
 "a (to, at), di (of), da (from, since, at someone's place, by), in (in), su (on), con, per, tra / fra.\nThey merge with the article: a + il = al, di + il = del, da + il = dal, in + il = nel, su + il = sul; likewise allo, alla, ai, agli, alle; della, nella, sulla…\nCities: a Roma; countries: in Italia. At someone's place: da Maria."),
 [("Vado al cinema.", "Je vais au cinéma.", "I am going to the cinema."), ("Vivo in Italia da due anni.", "J'habite en Italie depuis deux ans.", "I have lived in Italy for two years.")],
 r"\b(al|alla|del|della|nel|nella|dal|dalla|sul|sulla)\b", ['al', 'alla', 'del', 'della', 'nel', 'nella', 'dal', 'sul']),
pt('A1', 'questions', ('Poser une question',
 "L'ordre des mots ne change pas ; seule l'intonation monte : Parli inglese?\nMots interrogatifs : che cosa / cosa (quoi), chi (qui), dove (où), quando, come, perché (pourquoi et parce que), quanto, quale."),
 ('Asking questions',
 "Word order does not change; only the intonation rises: Parli inglese?\nQuestion words: che cosa / cosa (what), chi (who), dove (where), quando, come, perché (both why and because), quanto, quale."),
 [("Dove abiti?", "Où habites-tu ?", "Where do you live?"), ("Quanto costa?", "Combien ça coûte ?", "How much is it?")],
 r"^(Dove|Chi|Quando|Come|Perché|Quanto|Cosa|Quale)\b", ['Dove', 'Chi', 'Quando', 'Come', 'Perché', 'Quanto']),
pt('A2', 'passato-prossimo', ('Le passé composé (passato prossimo)',
 "avere ou essere au présent + participe (-ato, -uto, -ito : parlato, venduto, dormito).\n« Essere » avec les verbes de mouvement et d'état (andare, venire, partire, nascere, restare) et les pronominaux ; le participe s'accorde alors avec le sujet : Maria è andata.\nParticipes irréguliers : fatto, detto, visto, preso, scritto, letto, messo, stato, venuto, aperto, chiuso."),
 ('The present perfect (passato prossimo)',
 "Present of avere or essere + participle (-ato, -uto, -ito: parlato, venduto, dormito).\n“Essere” with verbs of movement and state (andare, venire, partire, nascere, restare) and reflexives; the participle then agrees with the subject: Maria è andata.\nIrregular participles: fatto, detto, visto, preso, scritto, letto, messo, stato, venuto, aperto, chiuso."),
 [("Ho mangiato una pizza.", "J'ai mangé une pizza.", "I ate a pizza."), ("Siamo andati al mare.", "Nous sommes allés à la mer.", "We went to the seaside.")],
 r"\b(ho|hai|ha|abbiamo|hanno|sono|è|siamo) (?:\w+ato|\w+uto|\w+ito|fatto|detto|visto|preso|scritto|stato|andat[oaie]|venut[oaie])\b", ['ho', 'hai', 'ha', 'abbiamo', 'sono', 'è']),
pt('A2', 'imperfetto', ("L'imparfait",
 "parlavo, parlavi, parlava, parlavamo, parlavate, parlavano ; prendevo ; dormivo. essere : ero, eri, era, eravamo, eravate, erano. fare → facevo, dire → dicevo, bere → bevevo.\nIl décrit une habitude, un décor, une action en cours ; le passé composé rapporte l'événement : Mentre mangiavo, è arrivato Paolo."),
 ('The imperfect',
 "parlavo, parlavi, parlava, parlavamo, parlavate, parlavano; prendevo; dormivo. essere: ero, eri, era, eravamo, eravate, erano. fare → facevo, dire → dicevo, bere → bevevo.\nIt describes habits, background and ongoing actions; the present perfect reports the event: Mentre mangiavo, è arrivato Paolo."),
 [("Da bambino giocavo a calcio.", "Enfant, je jouais au football.", "As a child I used to play football."), ("Era tardi.", "Il était tard.", "It was late.")],
 r"\b(ero|eri|era|eravamo|erano|avevo|aveva|avevano|faceva|c'era|stava|voleva)\b", None),
pt('A2', 'pronoms', ('Les pronoms compléments',
 "Directs : mi, ti, lo / la, ci, vi, li / le. Indirects : mi, ti, gli / le, ci, vi, gli.\nIls précèdent le verbe conjugué (Lo vedo) ou se soudent à l'infinitif (vederlo) et à l'impératif (prendilo).\nCombinés : me lo, te lo, glielo, ce lo, ve lo. « Ne » remplace di + nom ou une quantité (Ne voglio due) ; « ci » remplace un lieu (Ci vado)."),
 ('Object pronouns',
 "Direct: mi, ti, lo / la, ci, vi, li / le. Indirect: mi, ti, gli / le, ci, vi, gli.\nThey precede the conjugated verb (Lo vedo) or attach to an infinitive (vederlo) and to commands (prendilo).\nCombined: me lo, te lo, glielo, ce lo, ve lo. “Ne” replaces di + noun or a quantity (Ne voglio due); “ci” replaces a place (Ci vado)."),
 [("Non lo so.", "Je ne le sais pas.", "I don't know."), ("Ti amo.", "Je t'aime.", "I love you.")],
 r"\b([Ll]o|[Ll]a|[Ll]i|[Ll]e|[Mm]i|[Tt]i|[Cc]i|[Nn]e) (?:so|vedo|conosco|voglio|ho|ha|piace|piacciono|amo|dico|sento|vado)\b", ['lo', 'la', 'mi', 'ti', 'ci', 'ne']),
pt('A2', 'piacere-reflexifs', ('Piacere et les verbes pronominaux',
 "« Piacere » se construit comme « plaire » : Mi piace il gelato ; Mi piacciono i gatti. A Marco piace leggere.\nPronominaux : mi alzo, ti alzi, si alza, ci alziamo, vi alzate, si alzano. Au passé composé, toujours avec essere : mi sono alzato."),
 ('Piacere and reflexive verbs',
 "“Piacere” works like “to please”: Mi piace il gelato; Mi piacciono i gatti. A Marco piace leggere.\nReflexives: mi alzo, ti alzi, si alza, ci alziamo, vi alzate, si alzano. In the present perfect always with essere: mi sono alzato."),
 [("Mi piace la musica.", "J'aime la musique.", "I like music."), ("Come ti chiami?", "Comment t'appelles-tu ?", "What is your name?")],
 r"\b(piace|piacciono)\b", ['piace', 'piacciono', 'piaccio', 'piaci']),
pt('A2', 'futur', ('Le futur',
 "parlerò, parlerai, parlerà, parleremo, parlerete, parleranno (les verbes en -are changent a en e) ; prenderò ; dormirò.\nRadicaux irréguliers : sarò (essere), avrò, andrò, farò, verrò, potrò, dovrò, vorrò, vedrò, saprò.\nLe futur sert aussi à supposer : Sarà stanco (il doit être fatigué). Pour un projet proche, le présent suffit : Domani parto."),
 ('The future',
 "parlerò, parlerai, parlerà, parleremo, parlerete, parleranno (-are verbs change a to e); prenderò; dormirò.\nIrregular stems: sarò (essere), avrò, andrò, farò, verrò, potrò, dovrò, vorrò, vedrò, saprò.\nThe future also expresses a guess: Sarà stanco (he must be tired). For near plans the present is enough: Domani parto."),
 [("Domani pioverà.", "Demain il pleuvra.", "It will rain tomorrow."), ("Ti chiamerò stasera.", "Je t'appellerai ce soir.", "I will call you tonight.")],
 r"\b(sarò|sarà|saranno|avrò|avrà|andrò|andrà|farò|farà|verrò|verrà|potrò|potrà)\b", None),
pt('B1', 'conditionnel', ('Le conditionnel',
 "Même radical que le futur + ei, esti, ebbe, emmo, este, ebbero : parlerei, saresti, avrebbe, vorremmo.\nPolitesse : Vorrei un caffè. Potrebbe aiutarmi? Conseil : Dovresti riposare.\nPassé : avrei / sarei + participe (Sarei venuto) ; c'est aussi le « futur dans le passé » : Ha detto che sarebbe venuto."),
 ('The conditional',
 "Future stem + ei, esti, ebbe, emmo, este, ebbero: parlerei, saresti, avrebbe, vorremmo.\nPoliteness: Vorrei un caffè. Potrebbe aiutarmi? Advice: Dovresti riposare.\nPast: avrei / sarei + participle (Sarei venuto); it also expresses the future in the past: Ha detto che sarebbe venuto."),
 [("Vorrei un bicchiere d'acqua.", "Je voudrais un verre d'eau.", "I would like a glass of water."), ("Dovresti dormire di più.", "Tu devrais dormir davantage.", "You should sleep more.")],
 r"\b(vorrei|potrei|potresti|potrebbe|dovrei|dovresti|sarebbe|avrei|farei|piacerebbe)\b", None),
pt('B1', 'imperatif', ("L'impératif",
 "Tu : parla, prendi, dormi (finisci). Noi : parliamo. Voi : parlate. Lei (politesse) : subjonctif — parli, prenda, dorma.\nIrréguliers à tu : va', fa', di', da', sta', sii, abbi, vieni.\nNégation à tu : non + infinitif (Non parlare!). Les pronoms se soudent : dimmi, fallo, alzati ; avec Lei, ils précèdent : mi dica."),
 ('The imperative',
 "Tu: parla, prendi, dormi (finisci). Noi: parliamo. Voi: parlate. Lei (formal): subjunctive — parli, prenda, dorma.\nIrregular tu forms: va', fa', di', da', sta', sii, abbi, vieni.\nNegative tu: non + infinitive (Non parlare!). Pronouns attach: dimmi, fallo, alzati; with Lei they go before: mi dica."),
 [("Vieni qui!", "Viens ici !", "Come here!"), ("Non ti preoccupare.", "Ne t'inquiète pas.", "Don't worry.")],
 r"^(Vieni|Dimmi|Guarda|Aspetta|Ascolta|Prendi|Scusa|Senti|Stai|Fammi)\b", None),
pt('B1', 'comparaison-relatifs', ('Comparer et relier',
 "più … di, meno … di devant un nom ou un pronom (più alto di me) ; « che » pour comparer deux adjectifs, verbes ou compléments (più bello che utile). Égalité : (così) … come, (tanto) … quanto. Irréguliers : migliore, peggiore, maggiore, minore ; meglio, peggio. Superlatif : il più bello ; bellissimo.\nRelatifs : che (sujet et objet), cui après préposition (la città in cui vivo), il quale ; chi = celui qui."),
 ('Comparing and linking',
 "più … di, meno … di before a noun or pronoun (più alto di me); “che” to compare two adjectives, verbs or phrases (più bello che utile). Equality: (così) … come, (tanto) … quanto. Irregular: migliore, peggiore, maggiore, minore; meglio, peggio. Superlative: il più bello; bellissimo.\nRelatives: che (subject and object), cui after a preposition (la città in cui vivo), il quale; chi = whoever."),
 [("È più alto di me.", "Il est plus grand que moi.", "He is taller than me."), ("Il libro che leggo è interessante.", "Le livre que je lis est intéressant.", "The book I am reading is interesting.")],
 r"\b(più|meno|meglio|peggio|migliore)\b", ['più', 'meno', 'meglio', 'peggio', 'migliore']),
pt('B1', 'congiuntivo', ('Le subjonctif présent',
 "parli, parli, parli, parliamo, parliate, parlino ; prenda… prendano ; dorma… dormano. Irréguliers : sia, abbia, vada, faccia, venga, possa, voglia, sappia, dia, stia, dica.\nAprès les verbes d'opinion, de doute, de souhait et d'émotion : Penso che sia vero. Spero che tu venga. Voglio che tu lo sappia. Aussi après benché, affinché, prima che, a meno che.\nSi les deux sujets sont identiques : di + infinitif (Penso di partire)."),
 ('The present subjunctive',
 "parli, parli, parli, parliamo, parliate, parlino; prenda… prendano; dorma… dormano. Irregular: sia, abbia, vada, faccia, venga, possa, voglia, sappia, dia, stia, dica.\nAfter verbs of opinion, doubt, wish and emotion: Penso che sia vero. Spero che tu venga. Voglio che tu lo sappia. Also after benché, affinché, prima che, a meno che.\nIf both subjects are the same: di + infinitive (Penso di partire)."),
 [("Penso che tu abbia ragione.", "Je pense que tu as raison.", "I think you are right."), ("Spero che stiate bene.", "J'espère que vous allez bien.", "I hope you are well.")],
 r"\bche (?:\w+ )?(sia|siano|abbia|abbiano|venga|vada|faccia|possa|stia|sappia)\b", None),
pt('B2', 'ipotetico', ("Le subjonctif imparfait et l'hypothèse",
 "parlassi, parlassi, parlasse, parlassimo, parlaste, parlassero ; essere : fossi, fosse, fossero ; avere : avessi ; fare : facessi.\nHypothèse possible ou irréelle : se + subjonctif imparfait, conditionnel. Se avessi tempo, viaggerei.\nIrréel du passé : Se avessi saputo, sarei venuto.\nCondition réelle : indicatif des deux côtés. Se piove, resto a casa."),
 ('The imperfect subjunctive and if-clauses',
 "parlassi, parlassi, parlasse, parlassimo, parlaste, parlassero; essere: fossi, fosse, fossero; avere: avessi; fare: facessi.\nPossible or unreal condition: se + imperfect subjunctive, conditional. Se avessi tempo, viaggerei.\nUnreal past: Se avessi saputo, sarei venuto.\nReal condition: indicative on both sides. Se piove, resto a casa."),
 [("Se fossi ricco, comprerei una barca.", "Si j'étais riche, j'achèterais un bateau.", "If I were rich, I would buy a boat.")],
 r"\b[Ss]e (?:\w+ )?(fossi|fosse|avessi|avesse|potessi|potesse|sapessi|facessi)\b", None),
pt('B2', 'passato-remoto', ('Le passé simple (passato remoto) et le passif',
 "Temps du récit écrit et de l'histoire, courant à l'oral dans le sud : parlai, parlasti, parlò, parlammo, parlaste, parlarono. Irréguliers : fui, fu, furono (essere) ; ebbi, ebbe ; feci, fece ; dissi, disse ; venni, venne ; vidi, vide.\nPassif : essere (ou venire) + participe accordé + da. Il libro è stato scritto da Eco. « Si » impersonnel : In Italia si mangia bene."),
 ('The passato remoto and the passive',
 "The tense of written narrative and history, common in speech in the south: parlai, parlasti, parlò, parlammo, parlaste, parlarono. Irregular: fui, fu, furono (essere); ebbi, ebbe; feci, fece; dissi, disse; venni, venne; vidi, vide.\nPassive: essere (or venire) + agreeing participle + da. Il libro è stato scritto da Eco. Impersonal “si”: In Italia si mangia bene."),
 [("Dante nacque a Firenze.", "Dante naquit à Florence.", "Dante was born in Florence."), ("Qui si parla italiano.", "Ici on parle italien.", "Italian is spoken here.")],
 r"\b(fu|furono|disse|fece|ebbe|venne|vide|andò|nacque|morì)\b", None),
]
